        move('cold_run_balak (CALL) — BK.phinehas_and_midian(balaam_death) = %s' % BK_BALAAM[0], "the row balaam_death = %s (the settings %s)" % (data['balaam_death']['value'], sorted(data['balaam_death']['settings'])))
